#include "Studio.h"
#include <cmath>
namespace pulse {
using namespace juce;
void Studio::runModulationChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    cancelNoteTool();closeCommandPalette();setSize(1180,800);resetLayout();
    auto draw=[&]{hits.clear();Image image(Image::RGB,getWidth(),getHeight(),true);Graphics g(image);paint(g);};
    auto event=[&](Point<float> p,int mods=ModifierKeys::leftButtonModifier){auto time=Time::getCurrentTime();return MouseEvent(Desktop::getInstance().getMainMouseSource(),p,ModifierKeys(mods),1,0,0,0,0,this,this,time,p,time,1,false);};
    for(auto kind:{ModulationKind::flanger,ModulationKind::phaser}){
        int slotIndex=kind==ModulationKind::flanger?4:5,first=kind==ModulationKind::flanger?flangerMix:phaserMix;String name=modulationName(kind);
        project=emptyProject();project.bpm=120;project.loop=false;currentFile=File();selectedTrack=7;selectedNotes.clear();selectedNote=-1;project.patterns[0].length=4;lane()={{0,1,60,.8f}};undoStack.clear();redoStack.clear();publish();perform(stop);showPane(mixerPane);draw();
        auto slot=std::find_if(hits.begin(),hits.end(),[&](const Hit& h){return h.pane==mixerPane&&h.action==effectsOpen&&h.data==slotIndex;});check(slot!=hits.end(),name+" has an actual Mixer effect slot");if(slot!=hits.end()){auto click=event(slot->rect.getCentre());mouseDown(click);mouseUp(click);}check(activePane==effectsPane&&selectedEffect==slotIndex,name+" slot opens its editor page");
        auto original=JSON::toString(projectToJson(project));perform(effectToggle,slotIndex);auto& initialMixer=project.tracks[7].mixer;bool enabled=(kind==ModulationKind::flanger?initialMixer.flanger:initialMixer.phaser).enabled;check(enabled&&undoStack.size()==1,name+" enable is one project edit");perform(undoAction);check(JSON::toString(projectToJson(project))==original,name+" bypass Undo preserves all notes, settings and variable length");perform(redoAction);
        draw();std::set<int> knobs,tabs;bool fits=true;for(const auto& hit:hits)if(hit.pane==effectsPane){fits&=workspaceBounds().contains(hit.rect);if(hit.action>=first&&hit.action<first+6)knobs.insert(hit.action);if(hit.action==effectsTab)tabs.insert(hit.data);}check(fits&&knobs.size()==6&&tabs.size()==6,name+" six knobs and all effect tabs fit the compact editor");snapshot(folder.getChildFile(name+".png"));
        auto get=[&]()->const ModulationSettings&{return kind==ModulationKind::flanger?project.tracks[7].mixer.flanger:project.tracks[7].mixer.phaser;};auto before=get();undoStack.clear();auto knob=std::find_if(hits.begin(),hits.end(),[&](const Hit& h){return h.action==first+1;});if(knob!=hits.end()){auto point=knob->rect.getCentre();mouseDown(event(point));mouseDrag(event(point+Point<float>(0,-35)));mouseUp(event(point));}check(get().rate>before.rate&&undoStack.size()==1,name+" mouse drag changes logarithmic rate in one undo");perform(undoAction);check(get()==before,name+" drag Undo restores complete settings");
        draw();knob=std::find_if(hits.begin(),hits.end(),[&](const Hit& h){return h.action==first+4;});MouseWheelDetails wheel;wheel.deltaY=.1f;if(knob!=hits.end())mouseWheelMove(event(knob->rect.getCentre()),wheel);check(get().feedback>before.feedback,name+" wheel edits signed feedback");perform(undoAction);checkpoint();setParameter(first+3,7,1);draw();knob=std::find_if(hits.begin(),hits.end(),[&](const Hit& h){return h.action==first+3;});if(knob!=hits.end()){auto click=event(knob->rect.getCentre(),ModifierKeys::leftButtonModifier|ModifierKeys::altModifier);mouseDown(click);mouseUp(click);}check(std::abs(get().centre-modulationSpecs(kind)[3].initial)<.0001,name+" Alt-click resets centre to its musical default");perform(undoAction);check(std::abs(get().centre-modulationSpecs(kind)[3].high)<.001,name+" reset is undoable");
        auto entries=paletteEntries();int commands=0;for(auto i:searchCommands(entries,"channel "+name))if(entries[(size_t)i].data==slotIndex&&(entries[(size_t)i].action==effectsOpen||entries[(size_t)i].action==effectToggle))++commands;check(commands==2,name+" open/bypass commands are searchable");
        auto frozen=JSON::toString(projectToJson(project));recording=true;perform(effectToggle,slotIndex);setParameter(first,7,.9f);check(JSON::toString(projectToJson(project))==frozen,name+" recording locks bypass and parameter edits");recording=false;setParameter(first,7,std::numeric_limits<float>::quiet_NaN());check(JSON::toString(projectToJson(project))==frozen,name+" ignores nonfinite editor values");
        auto file=folder.getChildFile(name+"-session.pulse");Project reopened;check(saveProject(project,file).wasOk()&&loadProject(file,reopened).wasOk()&&reopened.patterns[0].length==4&&(kind==ModulationKind::flanger?reopened.tracks[7].mixer.flanger:reopened.tracks[7].mixer.phaser)==get(),name+" editor project save/reopen retains complete effect state and variable steps");
        perform(play);AudioBuffer<float> output(2,512);float peak=0;for(int i=0;i<80;++i){getNextAudioBlock(AudioSourceChannelInfo(&output,0,512));peak=jmax(peak,output.getMagnitude(0,0,512));}check(peak>.001f&&engine->playing.load(),name+" editor produces audible callback audio");perform(stop);getNextAudioBlock(AudioSourceChannelInfo(&output,0,512));check(output.getMagnitude(0,0,512)==0,name+" editor Stop clears effect feedback");
        project.tracks[5].isBus=true;selectedTrack=5;perform(effectToggle,slotIndex);check((kind==ModulationKind::flanger?project.tracks[5].mixer.flanger:project.tracks[5].mixer.phaser).enabled,name+" is editable on a Mixer bus");selectedTrack=7;showPane(effectsPane);draw();
    }
}
}
